#!/usr/bin/env node
/**
 * Prepares the local head-tracking runtime so the game never loads tracking
 * code or models from a CDN.
 *
 *   public/mediapipe/wasm/    MediaPipe Tasks Vision WASM runtime, copied from the pinned
 *                             npm package (git-ignored, regenerated by this script)
 *   public/mediapipe/models/  face_landmarker.task (committed; re-downloaded only when it
 *                             is missing or fails verification)
 *
 * Usage:  node tools/fetch-tracking-assets.mjs [--check] [--force-model]
 *   --check        verify only, never write or download (exit code 1 when something is missing)
 *   --force-model  download the model again even if the local copy verifies
 *
 * The script is idempotent and works offline as long as the model file is present.
 */
import { createHash } from 'node:crypto';
import { copyFile, mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const PKG_DIR = join(ROOT, 'node_modules', '@mediapipe', 'tasks-vision');
const WASM_SRC = join(PKG_DIR, 'wasm');
const WASM_DST = join(ROOT, 'public', 'mediapipe', 'wasm');
const MODEL_DIR = join(ROOT, 'public', 'mediapipe', 'models');

/** Version this project was verified against (must match package.json / the lockfile). */
const EXPECTED_TASKS_VISION = '1.2.3';

/**
 * Runtime files. The module variant is used by the inference worker (ES module
 * worker), the classic variant by the main-thread fallback (script tag loader).
 */
const WASM_FILES = [
  'vision_wasm_module_internal.js',
  'vision_wasm_module_internal.wasm',
  'vision_wasm_internal.js',
  'vision_wasm_internal.wasm',
];

/** Official, versioned model bundle (float16, version 1). */
const MODEL = {
  file: 'face_landmarker.task',
  url: 'https://storage.googleapis.com/mediapipe-models/face_landmarker/face_landmarker/float16/1/face_landmarker.task',
  bytes: 3758596,
  sha256: '64184e229b263107bc2b804c6625db1341ff2bb731874b0bcc2fe6544e0bc9ff',
};

const args = new Set(process.argv.slice(2));
const CHECK_ONLY = args.has('--check');
const FORCE_MODEL = args.has('--force-model');

const rel = (p) => relative(ROOT, p) || '.';
const log = (msg) => console.log(`[tracking-assets] ${msg}`);

async function sha256Of(path) {
  return createHash('sha256').update(await readFile(path)).digest('hex');
}

async function sameFile(a, b) {
  if (!existsSync(b)) return false;
  const [sa, sb] = await Promise.all([stat(a), stat(b)]);
  if (sa.size !== sb.size) return false;
  // Sizes match: compare content hashes (files are ~15 MB at most, this takes a few ms).
  const [ha, hb] = await Promise.all([sha256Of(a), sha256Of(b)]);
  return ha === hb;
}

async function copyWasmRuntime() {
  if (!existsSync(PKG_DIR)) {
    throw new Error(`@mediapipe/tasks-vision is not installed (${rel(PKG_DIR)} missing). Run "npm install" first.`);
  }
  const pkg = JSON.parse(await readFile(join(PKG_DIR, 'package.json'), 'utf8'));
  if (pkg.version !== EXPECTED_TASKS_VISION) {
    // Not fatal: the files are still copied from whatever is installed, but the
    // worker/main-thread loaders were only verified against the pinned version.
    log(`WARNING: installed @mediapipe/tasks-vision is ${pkg.version}, verified version is ${EXPECTED_TASKS_VISION}.`);
  }
  let copied = 0;
  let missing = 0;
  for (const name of WASM_FILES) {
    const src = join(WASM_SRC, name);
    const dst = join(WASM_DST, name);
    if (!existsSync(src)) {
      throw new Error(`Runtime file ${rel(src)} is missing from the installed package (version ${pkg.version}).`);
    }
    if (await sameFile(src, dst)) continue;
    if (CHECK_ONLY) {
      missing++;
      log(`missing or outdated: ${rel(dst)}`);
      continue;
    }
    await mkdir(WASM_DST, { recursive: true });
    await copyFile(src, dst);
    copied++;
  }
  if (!CHECK_ONLY) {
    await writeFile(
      join(WASM_DST, 'VERSION.json'),
      JSON.stringify({ package: '@mediapipe/tasks-vision', version: pkg.version, files: WASM_FILES }, null, 2) + '\n',
    );
  }
  log(
    CHECK_ONLY
      ? `wasm runtime ${missing === 0 ? 'ok' : `incomplete (${missing} file(s))`} (${rel(WASM_DST)})`
      : `wasm runtime ready in ${rel(WASM_DST)} (${copied} copied, ${WASM_FILES.length - copied} up to date, v${pkg.version})`,
  );
  return missing === 0;
}

async function verifyModel(path) {
  if (!existsSync(path)) return { ok: false, reason: 'missing' };
  const info = await stat(path);
  if (info.size !== MODEL.bytes) return { ok: false, reason: `size ${info.size} != ${MODEL.bytes}` };
  const hash = await sha256Of(path);
  if (hash !== MODEL.sha256) return { ok: false, reason: `sha256 ${hash} != ${MODEL.sha256}` };
  return { ok: true, reason: 'verified' };
}

async function downloadModel(target) {
  log(`downloading ${MODEL.url}`);
  let response;
  try {
    response = await fetch(MODEL.url, { redirect: 'follow' });
  } catch (error) {
    throw new Error(
      `Could not download the face landmarker model (${error?.cause?.code ?? error?.message ?? error}). ` +
        `Check the network / proxy, or place the file manually at ${rel(target)} ` +
        `(${MODEL.bytes} bytes, sha256 ${MODEL.sha256}).`,
    );
  }
  if (!response.ok) {
    throw new Error(`Model download failed: HTTP ${response.status} ${response.statusText} for ${MODEL.url}`);
  }
  const data = Buffer.from(await response.arrayBuffer());
  const hash = createHash('sha256').update(data).digest('hex');
  if (data.length !== MODEL.bytes || hash !== MODEL.sha256) {
    throw new Error(
      `Downloaded model does not match the pinned build (got ${data.length} bytes, sha256 ${hash}; ` +
        `expected ${MODEL.bytes} bytes, sha256 ${MODEL.sha256}). Refusing to install it.`,
    );
  }
  await mkdir(dirname(target), { recursive: true });
  const tmp = `${target}.download`;
  await writeFile(tmp, data);
  await rename(tmp, target);
}

async function ensureModel() {
  const target = join(MODEL_DIR, MODEL.file);
  const state = await verifyModel(target);
  if (state.ok && !FORCE_MODEL) {
    log(`model ok: ${rel(target)} (${MODEL.bytes} bytes, sha256 verified)`);
    return true;
  }
  if (CHECK_ONLY) {
    log(`model NOT ok: ${rel(target)} (${state.reason})`);
    return false;
  }
  if (!state.ok && state.reason !== 'missing') {
    log(`existing model failed verification (${state.reason}); downloading a fresh copy`);
    await rm(target, { force: true });
  }
  await downloadModel(target);
  log(`model installed: ${rel(target)} (${MODEL.bytes} bytes, sha256 verified)`);
  return true;
}

try {
  const wasmOk = await copyWasmRuntime();
  const modelOk = await ensureModel();
  if (CHECK_ONLY && !(wasmOk && modelOk)) {
    log('run "npm run assets:tracking" to fix');
    process.exit(1);
  }
} catch (error) {
  console.error(`[tracking-assets] ERROR: ${error?.message ?? error}`);
  process.exit(1);
}
